package entity

import "regexp"

// endpointIDPattern is the ID shape generated by the ID generator: the prefix and 26 Crockford
// base32 characters (api/openapi.yaml, schema EndpointID).
var endpointIDPattern = regexp.MustCompile(`^ep_[0-9A-HJKMNP-TV-Z]{26}$`)

// IsEndpointID reports whether s is a well-formed endpoint ID. Delivery answers 404 for anything
// else, so a malformed ID never reaches the database.
func IsEndpointID(s string) bool { return endpointIDPattern.MatchString(s) }
